export function createF8ExperimentDescriptor(): ExperimentDescriptorResponse {
  const parameterDescriptors = parameterInputs.map(
    ([
      fieldId,
      subsystem,
      groupId,
      order,
      pointer,
      valueType,
      enumValues,
      minimum,
      maximum,
      integerOnly,
      step,
      unit,
    ]) => ({
      field_id: fieldId,
      subsystem,
      group_id: groupId,
      display_order: order,
      request_json_pointer: pointer,
      value_type: valueType,
      enum_values: [...enumValues],
      minimum,
      maximum,
      minimum_inclusive: minimum !== null,
      maximum_inclusive: maximum !== null,
      integer_only: integerOnly,
      step,
      unit,
      required: false,
      explicit_default_available: false,
      capability_predicate: {
        capability_path: "/run_surface/override_parameter_field_ids",
        operator: "contains" as const,
        expected_value: fieldId,
        evaluated_available: true,
      },
      available: true,
      unavailable_reason: null,
      applicable_input_modes: ["controls" as const],
      applicable_scenarios: ["s1_des_example"],
    }),
  ) as ExperimentDescriptorResponse["parameter_descriptors"];

  return {
    schema_version: "tilesim.bridge.experiment_descriptor.v1",
    schema_set_revision: f8SchemaRevision,
    descriptor_id: "f8-s0-s1-s6-controlled-run-surface",
    descriptor_revision: f8DescriptorRevision,
    create_run_schema_identity: "tilesim.bridge.create_run_request.v1",
    scenarios: [
      {
        scenario_id: "s1_des_example",
        label: "S1 -> S6 synthetic runtime example",
        available: true,
        unavailable_reason: null,
      },
    ],
    requested_fidelity_options: [
      {
        fidelity_policy: "default",
        requested_tier: "policy_default",
        available: true,
        unavailable_reason: null,
        capability_predicate: null,
      },
      {
        fidelity_policy: "des",
        requested_tier: "DES",
        available: true,
        unavailable_reason: null,
        capability_predicate: null,
      },
      {
        fidelity_policy: "cycle",
        requested_tier: "Cycle",
        available: false,
        unavailable_reason: "explicit_s6_cycle_hotspot_request_surface_not_exposed",
        capability_predicate: {
          capability_path: "/run_surface/cycle_hotspot_request_available",
          operator: "equals",
          expected_value: true,
          evaluated_available: false,
        },
      },
    ],
    gpu_participation_modes: [{ gpu_participation_mode: "gpu_free", available: true, unavailable_reason: null }],
    input_modes: [
      { input_mode: "controls", available: true, unavailable_reason: null },
      { input_mode: "json", available: true, unavailable_reason: null },
      { input_mode: "trace_package", available: true, unavailable_reason: null },
    ],
    design_space_modes: [
      { design_space_mode: "built_in_synthetic", available: true, unavailable_reason: null },
      { design_space_mode: "strict_s6_manifest", available: true, unavailable_reason: null },
    ],
    source_mode_options: [
      {
        source_mode: "synthetic_trace",
        available: true,
        unavailable_reason: null,
        allowed_claim_scope: "synthetic_consistency_and_exploratory_s6_only",
        calibration_requirement: "not_required_for_consistency_only",
        applicable_input_modes: ["controls", "json", "trace_package"],
        capability_predicate: null,
      },
      {
        source_mode: "real_trace",
        available: false,
        unavailable_reason: "real_trace_submission_not_exposed",
        allowed_claim_scope: "held_out_fidelity_only_with_real_calibrated_evidence",
        calibration_requirement: "calibrated_and_held_out_validation_required",
        applicable_input_modes: ["json", "trace_package"],
        capability_predicate: {
          capability_path: "/run_surface/real_trace_submission_available",
          operator: "equals",
          expected_value: true,
          evaluated_available: false,
        },
      },
      {
        source_mode: "compatibility_harness_trace",
        available: false,
        unavailable_reason: "compatibility_harness_submission_not_exposed",
        allowed_claim_scope: "semantic_extraction_and_compatibility_consistency_only",
        calibration_requirement: "not_ground_truth_fidelity_evidence",
        applicable_input_modes: ["json", "trace_package"],
        capability_predicate: {
          capability_path: "/run_surface/compatibility_harness_submission_available",
          operator: "equals",
          expected_value: true,
          evaluated_available: false,
        },
      },
    ],
    parameter_groups: [
      { group_id: "s0_workload", subsystem: "S0", display_order: 100, status: "exposed" },
      { group_id: "s1_runtime", subsystem: "S1", display_order: 200, status: "exposed" },
      { group_id: "s6_fabric", subsystem: "S6", display_order: 600, status: "exposed" },
    ],
    subsystem_parameter_coverage: (["S0", "S1", "S2", "S3", "S4", "S5", "S6"] as const).map((subsystem) => ({
      subsystem,
      status: ["S0", "S1", "S6"].includes(subsystem) ? ("exposed" as const) : ("not_exposed" as const),
      parameter_field_ids: parameterDescriptors
        .filter((field) => field.subsystem === subsystem)
        .map((field) => field.field_id),
      reason: ["S0", "S1", "S6"].includes(subsystem) ? null : "no_formal_create_run_parameter_surface",
    })) as ExperimentDescriptorResponse["subsystem_parameter_coverage"],
    parameter_descriptors: parameterDescriptors,
    resolved_fidelity_source: "run_execution_envelope_and_validation_reports",
  };
}
